class Spell {
    constructor(name) {
        this.name = name;
    }

    cast() {
        return `${this.name} is cast.`;
    }
}

class Fireball extends Spell {
    constructor(name, damage) {
        super(name);
        this.damage = damage;
    }

    cast() {
        return `Casting ${this.name} for ${this.damage} damage!`;
    }
}

class Heal extends Spell {
    constructor(name, healAmount) {
        super(name);
        this.healAmount = healAmount;
    }

    cast() {
        return `Casting ${this.name} restoring ${this.healAmount} health!`;
    }
}

const fireballSpell = new Fireball("Firebolt", 25);
const healSpell = new Heal("Minor Heal", 30);

console.log(fireballSpell.cast());
console.log(healSpell.cast());

